   306→
   307→	/**
   308→	 * @brief Writes bytes from the provided buffer to the stream.
   309→	 * 
   310→	 * @tparam T POD type.
   311→	 * @param data Pointer to the buffer from which data will be copied to the stream.
   312→	 * @param count The number of elements to write.
   313→	 */
   314→	template<pod T>
   315→	void put(const T* data, std::size_t count) {
   316→		assert(data);
   317→		const auto write_size = count * sizeof(T);
   318→		write(data, write_size);
   319→	}
   320→
   321→	/**
   322→	 * @brief Writes the data from the iterator range to the stream.
   323→	 * 
   324→	 * @tparam It The iterator type.
   325→	 * @param begin Iterator to the beginning of the data.
   326→	 * @param end Iterator to the end of the data.
   327→	 */
   328→	template<typename It>
   329→	void put(It begin, const It end) {
   330→		for(auto it = begin; it != end; ++it) {
   331→			*this << *it;
   332→		}
   333→	}
   334→
   335→	/**
   336→	 * @brief Allows for writing a provided byte value a specified number of times to
   337→	 * the stream.
   338→	 * 
   339→	 * @tparam size The number of bytes to generate.
   340→	 * @param value The byte value that will fill the specified number of bytes.
   341→	 */
   342→	template<std::size_t size>
   343→	void fill(const std::uint8_t value) {
   344→		const auto filled = generate_filled<size>(value);
   345→		write(filled.data(), filled.size());
   346→	}
   347→
   348→	/**  Misc functions **/ 
   349→
   350→	/**
   351→	 * @brief Determines whether this container can write seek.
   352→	 * 
   353→	 * @return Whether this container is capable of write seeking.
   354→	 */
   355→	bool can_write_seek() const {
   356→		return buffer_.can_write_seek();
   357→	}
   358→
   359→	/**
   360→	 * @brief Performs write seeking within the container.
   361→	 * 
   362→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   363→	 * @param offset The offset relative to the seek direction or the absolute value
   364→	 * when using absolute seeking.
   365→	 */
   366→	void write_seek(const stream_seek direction, const std::size_t offset) {
   367→		if(direction == stream_seek::sk_stream_absolute) {
   368→			if(offset >= total_write_) {
   369→				buffer_.write_seek(buffer_seek::sk_forward, offset - total_write_);
   370→			} else {
   371→				buffer_.write_seek(buffer_seek::sk_backward, total_write_ - offset);
   372→			}
   373→
   374→			total_write_ = offset;
   375→		} else {
   376→			buffer_.write_seek(static_cast<buffer_seek>(direction), offset);
   377→		}
   378→	}
   379→
   380→	/**
   381→	 * @brief Returns the size of the container.
   382→	 * 
   383→	 * @return The number of bytes of data available to read within the stream.
   384→	 */
   385→	std::size_t size() const {
   386→		return buffer_.size();
   387→	}
   388→
   389→	/**
   390→	 * @brief Whether the container is empty.
   391→	 * 
   392→	 * @return Returns true if the container is empty (has no data to be read).
   393→	 */
   394→	[[nodiscard]]
   395→	bool empty() const {
   396→		return buffer_.empty();
   397→	}
   398→
   399→	/**
   400→	 * @return The total number of bytes written to the stream.
   401→	 */
   402→	std::size_t total_write() const {
   403→		return total_write_;
   404→	}
   405→
   406→	/** 
   407→	 * @brief Get a pointer to the buffer write interface.
   408→	 *
   409→	 * @return Pointer to the buffer write interface. 
   410→	 */
   411→	buffer_write* buffer() {
   412→		return &buffer_;
   413→	}
   414→
   415→	/** 
   416→	 * @brief Get a pointer to the buffer write interface.
   417→	 *
   418→	 * @return Pointer to the buffer write interface. 
   419→	 */
   420→	const buffer_write* buffer() const {
   421→		return &buffer_;
   422→	}
   423→};
