    18→template<typename buf_type>
    19→concept writeable =
    20→	requires(buf_type t, void* v, typename buf_type::size_type s) {
    21→		{ t.write(v, s) } -> std::same_as<void>;
    22→};
    23→
    24→template<typename buf_type>
    25→concept seekable = requires(buf_type t) {
    26→	std::is_same_v<typename buf_type::seeking, supported>;
    27→};
    28→
    29→template<typename buf_type>
    30→concept contiguous = requires(buf_type t) {
    31→	std::is_same_v<typename buf_type::contiguous, is_contiguous>;
    32→};
    33→
    34→template<typename T>
    35→concept arithmetic = std::integral<T> || std::floating_point<T>;
    36→
    37→template<typename T>
    38→concept byte_type = sizeof(T) == 1;
    39→
    40→template<typename T>
    41→concept byte_oriented = byte_type<typename T::value_type>;
    42→
    43→template<typename T>
    44→concept pod = std::is_standard_layout_v<T> && std::is_trivial_v<T>;
    45→
    46→template<typename T>
    47→concept has_resize_overwrite =
    48→	requires(T t) {
    49→		{ t.resize_and_overwrite(typename T::size_type(), [](char*, T::size_type) {}) } -> std::same_as<void>;
    50→};
    51→
    52→template<typename T>
    53→concept has_resize = 
    54→	requires(T t) {
    55→		{ t.resize(typename T::size_type() ) } -> std::same_as<void>;
    56→};
    57→
    58→template<typename T>
    59→concept has_reserve = 
    60→	requires(T t) {
    61→		{ t.reserve(typename T::size_type() ) } -> std::same_as<void>;
    62→};
    63→
    64→template<typename T>
    65→concept has_clear = 
    66→	requires(T t) {
    67→		{ t.clear() } -> std::same_as<void>;
    68→};
    69→
    70→template<typename T, typename U>
    71→concept has_shl_override =
    72→	requires(T t, U& u) {
    73→		{ t.operator<<(u) } -> std::same_as<U&>;
    74→};
    75→
    76→template<typename T, typename U>
    77→concept has_shr_override =
    78→	requires(T t, U& u) {
    79→		{ t.operator>>(u) } -> std::same_as<U&>;
    80→};
    81→
    82→template<typename T, typename U>
    83→concept has_serialise =
    84→	requires(T t, stream_write_adaptor<U>& u) {
    85→		{ t.serialise(u) } -> std::same_as<void>;
    86→};
    87→
    88→template<typename T, typename U>
    89→concept has_deserialise =
    90→	requires(T t, stream_read_adaptor<U>& u) {
    91→		{ t.serialise(u) } -> std::same_as<void>;
    92→};
    93→
    94→template<typename T>
    95→concept is_iterable =
    96→	requires(T t) {
    97→		t.begin(); t.end();
    98→};
    99→
   100→template<typename T, typename U>
   101→concept memcpy_read =
   102→	pod<typename T::value_type> && std::ranges::contiguous_range<T>
   103→		&& !has_shr_override<typename T::value_type, U>
   104→		&& !has_deserialise<typename T::value_type, U>;
   105→
   106→template<typename T, typename U>
   107→concept memcpy_write =
   108→	pod<typename T::value_type> && std::ranges::contiguous_range<T>
   109→		&& !has_shl_override<typename T::value_type, U>
   110→		&& !has_serialise<typename T::value_type, U>;
