   343→	}
   344→
   345→	/**
   346→	 * @return Pointer to the data available for reading.
   347→	 */
   348→	const value_type* data() const {
   349→		return read_ptr();
   350→	}
   351→
   352→	/**
   353→	 * @return Pointer to the data available for reading.
   354→	 */
   355→	value_type* data() {
   356→		return read_ptr();
   357→	}
   358→
   359→	/**
   360→	 * @return Pointer to the data available for reading.
   361→	 */
   362→	const value_type* read_ptr() const {
   363→		return buffer_.data() + read_;
   364→	}
   365→
   366→	/**
   367→	 * @return Pointer to the data available for reading.
   368→	 */
   369→	value_type* read_ptr() {
   370→		return buffer_.data() + read_;
   371→	}
   372→
   373→	/**
   374→	 * @return Pointer to the location within the buffer where the next write
   375→	 * will be made.
   376→	 */
   377→	const value_type* write_ptr() const {
