    73→template<std::endian from, std::endian to>
    74→constexpr void conditional_reverse_inplace(arithmetic auto& value) {
    75→	using type = std::remove_reference_t<decltype(value)>;
    76→
    77→	if constexpr(from != to) {
    78→		if constexpr(std::is_same_v<type, float>) {
    79→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    80→		} else if constexpr(std::is_same_v<type, double>) {
    81→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    82→		} else {
    83→			value = std::byteswap(value);
    84→		}
    85→	}
    86→}
