    24→template<typename buf_type>
    25→concept seekable = requires(buf_type t) {
    26→	std::is_same_v<typename buf_type::seeking, supported>;
    27→};
    28→
    29→template<typename buf_type>
    30→concept contiguous = requires(buf_type t) {
    31→	std::is_same_v<typename buf_type::contiguous, is_contiguous>;
    32→};
