     9→#include <hexi/shared.h>
    10→#include <hexi/concepts.h>
    11→#include <hexi/exception.h>
    12→#include <ranges>
    13→#include <type_traits>
    14→#include <utility>
    15→#include <cassert>
    16→#include <cstddef>
    17→#include <cstring>
