    19→namespace hexi {
    20→
    21→using namespace detail;
    22→
    23→template<byte_oriented buf_type, bool space_optimise = true>
    24→requires std::ranges::contiguous_range<buf_type>
    25→class buffer_adaptor final {
    26→public:
    27→	using value_type  = typename buf_type::value_type;
    28→	using size_type   = typename buf_type::size_type;
    29→	using offset_type = typename buf_type::size_type;
    30→	using contiguous  = is_contiguous;
    31→	using seeking     = supported;
    32→
    33→	static constexpr auto npos { static_cast<size_type>(-1) };
    34→
    35→private:
    36→	buf_type& buffer_;
    37→	size_type read_;
    38→	size_type write_;
    39→
    40→public:
    41→	buffer_adaptor(buf_type& buffer)
    42→		: buffer_(buffer),
    43→		  read_(0),
    44→		  write_(buffer.size()) {}
    45→
    46→	buffer_adaptor(buf_type& buffer, init_empty_t)
    47→		: buffer_(buffer),
    48→		  read_(0),
    49→		  write_(0) {}
    50→
    51→	buffer_adaptor(buffer_adaptor&& rhs) = delete;
    52→	buffer_adaptor& operator=(buffer_adaptor&&) = delete;
    53→	buffer_adaptor& operator=(const buffer_adaptor&) = delete;
    54→	buffer_adaptor(const buffer_adaptor&) = delete;
    55→
    56→	/**
    57→	 * @brief Reads a number of bytes to the provided buffer.
    58→	 * 
    59→	 * @note The destination buffer must not overlap with the underlying buffer
    60→	 * being used by the buffer_adaptor.
    61→	 * 
    62→	 * @tparam T The destination type.
    63→	 * @param[out] destination The buffer to copy the data to.
    64→	 */
    65→	template<typename T>
    66→	void read(T* destination) {
    67→		read(destination, sizeof(T));
    68→	}
    69→
    70→	/**
    71→	 * @brief Reads a number of bytes to the provided buffer.
    72→	 * 
    73→	 * @note The destination buffer must not overlap with the underlying buffer
    74→	 * being used by the buffer_adaptor.
    75→	 * 
    76→	 * @param[out] destination The buffer to copy the data to.
    77→	 * @param length The number of bytes to read into the buffer.
    78→	 */
    79→	void read(void* destination, size_type length) {
    80→		assert(destination);
    81→		copy(destination, length);
    82→		read_ += length;
    83→
    84→		if constexpr(space_optimise) {
    85→			if(read_ == write_) {
    86→				read_ = write_ = 0;
    87→			}
    88→		}
    89→	}
    90→
    91→	/**
    92→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    93→	 * the read cursor.
    94→	 * 
    95→	 * @param[out] destination The buffer to copy the data to.
    96→	 */
    97→	template<typename T>
    98→	void copy(T* destination) const {
    99→		copy(destination, sizeof(T));
   100→	}
   101→
   102→	/**
   103→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   104→	 * the read cursor.
   105→	 * 
   106→	 * @note The destination buffer must not overlap with the underlying buffer
   107→	 * being used by the buffer_adaptor.
   108→	 * 
   109→	 * @param[out] destination The buffer to copy the data to.
   110→	 * @param length The number of bytes to copy.
   111→	 */
   112→	void copy(void* destination, size_type length) const {
   113→		assert(destination && !region_overlap(buffer_.data(), buffer_.size(), destination, length));
   114→		std::memcpy(destination, read_ptr(), length);
   115→	}
   116→
   117→	/**
   118→	 * @brief Skip over a number of bytes.
   119→	 * 
   120→	 * Skips over a number of bytes from the container. This should be used
   121→	 * if the container holds data that you don't care about but don't want
   122→	 * to have to read it to another buffer to access data beyond it.
   123→	 * 
   124→	 * @param length The number of bytes to skip.
   125→	 */
   126→	void skip(size_type length) {
   127→		read_ += length;
   128→
   129→		if constexpr(space_optimise) {
   130→			if(read_ == write_) {
   131→				read_ = write_ = 0;
   132→			}
   133→		}
   134→	}
   135→
   136→	/**
   137→	 * @brief Write data to the container.
   138→	 * 
   139→	 * @note The source buffer must not overlap with the underlying buffer
   140→	 * being used by the buffer_adaptor.
   141→	 * 
   142→	 * @param source Pointer to the data to be written.
   143→	 */
   144→	void write(const auto& source) {
   145→		write(&source, sizeof(source));
   146→	}
   147→
   148→	/**
   149→	 * @brief Write provided data to the container.
   150→	 * 
   151→	 * @note The source buffer must not overlap with the underlying buffer
   152→	 * being used by the buffer_adaptor.
   153→	 * 
   154→	 * @param source Pointer to the data to be written.
   155→	 * @param length Number of bytes to write from the source.
   156→	 */
   157→	void write(const void* source, size_type length) {
   158→		assert(source && !region_overlap(source, length, buffer_.data(), buffer_.size()));
   159→		const auto min_req_size = write_ + length;
   160→
   161→		if(buffer_.size() < min_req_size) [[likely]] {
   162→			if constexpr(has_resize_overwrite<buf_type>) {
   163→				buffer_.resize_and_overwrite(min_req_size, [](char*, size_type size) {
   164→					return size;
   165→				});
   166→			} else if constexpr(has_resize<buf_type>) {
   167→				buffer_.resize(min_req_size);
   168→			} else {
   169→				HEXI_THROW(buffer_overflow(length, write_, free()));
   170→			}
   171→		}
   172→
   173→		std::memcpy(write_ptr(), source, length);
   174→		write_ += length;
   175→	}
   176→
   177→	/**
   178→	 * @brief Reserves a number of bytes within the container for future use.
   179→	 * 
   180→	 * @note This is a non-binding request, meaning the buffer may not reserve
   181→	 * any additional space, such as in the case where it is not supported.
   182→	 *
   183→	 * @param length The number of bytes that the container should reserve.
   184→	 */
   185→	void reserve(const size_type length) {
   186→		if constexpr(has_reserve<buf_type>) {
   187→			buffer_.reserve(length);
   188→		}
   189→	}
   190→
   191→	/**
   192→	 * @brief Attempts to locate the provided value within the container.
   193→	 * 
   194→	 * @param value The value to locate.
   195→	 * 
   196→	 * @return The position of value or npos if not found.
   197→	 */
   198→	size_type find_first_of(value_type val) const {
   199→		const auto data = read_ptr();
   200→
   201→		for(size_type i = 0, j = size(); i < j; ++i) {
   202→			if(data[i] == val) {
   203→				return i;
   204→			}
   205→		}
   206→
   207→		return npos;
   208→	}
   209→	
   210→	/**
   211→	 * @brief Returns the size of the container.
   212→	 * 
   213→	 * @return The number of bytes of data available to read within the container.
   214→	 */
   215→	size_type size() const {
   216→		return write_ - read_;
   217→	}
   218→
   219→	/**
   220→	 * @brief Whether the container is empty.
   221→	 * 
   222→	 * @return Returns true if the container is empty (has no data to be read).
   223→	 */
   224→	[[nodiscard]]
   225→	bool empty() const {
   226→		return read_ == write_;
   227→	}
   228→
   229→	/**
   230→	 * @brief Retrieves a reference to the specified index within the container.
   231→	 * 
   232→	 * @param index The index within the container.
   233→	 * 
   234→	 * @return A reference to the value at the specified index.
   235→	 */
   236→	value_type& operator[](const size_type index) {
   237→		return read_ptr()[index];
   238→	}
   239→
   240→	/**
   241→	 * @brief Retrieves a reference to the specified index within the container.
   242→	 * 
   243→	 * @param index The index within the container.
   244→	 * 
   245→	 * @return A reference to the value at the specified index.
   246→	 */
   247→	const value_type& operator[](const size_type index) const {
   248→		return read_ptr()[index];
   249→	}
   250→
   251→	/**
   252→	 * @brief Determine whether the adaptor supports write seeking.
   253→	 * 
   254→	 * This is determined at compile-time and does not need to checked at
   255→	 * run-time.
   256→	 * 
   257→	 * @return True if write seeking is supported, otherwise false.
   258→	 */
   259→	constexpr static bool can_write_seek() {
   260→		return std::is_same_v<seeking, supported>;
   261→	}
   262→
   263→	/**
   264→	 * @brief Performs write seeking within the container.
   265→	 * 
   266→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   267→	 * @param offset The offset relative to the seek direction or the absolute value
   268→	 * when using absolute seeking.
   269→	 */
   270→	void write_seek(const buffer_seek direction, const offset_type offset) {
   271→		switch(direction) {
   272→			case buffer_seek::sk_backward:
   273→				write_ -= offset;
   274→				break;
   275→			case buffer_seek::sk_forward:
   276→				write_ += offset;
   277→				break;
   278→			case buffer_seek::sk_absolute:
   279→				write_ = offset;
   280→		}
   281→	}
   282→
   283→	/**
   284→	 * @return Pointer to the data available for reading.
   285→	 */
   286→	auto read_ptr() const {
   287→		return buffer_.data() + read_;
   288→	}
   289→
   290→	/**
   291→	 * @return Pointer to the data available for reading.
   292→	 */
   293→	auto read_ptr() {
   294→		return buffer_.data() + read_;
   295→	}
   296→
   297→	/**
   298→	 * @return Pointer to the location within the buffer where the next write
   299→	 * will be made.
   300→	 */
   301→	auto write_ptr() const {
   302→		return buffer_.data() + write_;
   303→	}
