    89→	using type = std::remove_reference_t<decltype(value)>;
    90→
    91→	if(from != to) {
    92→		if constexpr(std::is_same_v<type, float>) {
    93→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    94→		} else if constexpr(std::is_same_v<type, double>) {
    95→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    96→		} else {
    97→			value = std::byteswap(value);
    98→		}
    99→	}
   100→}
   101→
   102→constexpr void little_to_native_inplace(arithmetic auto& value) {
   103→	conditional_reverse_inplace<std::endian::little, std::endian::native>(value);
   104→}
   105→
   106→constexpr void big_to_native_inplace(arithmetic auto& value) {
   107→	conditional_reverse_inplace<std::endian::big, std::endian::native>(value);
   108→}
   109→
   110→constexpr void native_to_little_inplace(arithmetic auto& value) {
   111→	conditional_reverse_inplace<std::endian::native, std::endian::little>(value);
   112→}
   113→
   114→constexpr void native_to_big_inplace(arithmetic auto& value) {
   115→	conditional_reverse_inplace<std::endian::native, std::endian::big>(value);
   116→}
   117→
   118→template<conversion _conversion>
   119→constexpr auto convert(arithmetic auto value) -> decltype(value) {
   120→	switch(_conversion) {
   121→		case conversion::big_to_native:
   122→			return big_to_native(value);
   123→		case conversion::native_to_big:
   124→			return native_to_big(value);
   125→		case conversion::little_to_native:
   126→			return little_to_native(value);
   127→		case conversion::native_to_little:
   128→			return native_to_little(value);
   129→		default:
   130→			std::unreachable();
   131→	};
   132→}
   133→
   134→struct adaptor_tag_t {};
   135→
   136→#define ENDIAN_ADAPTOR(name, func_to, func_from) \
   137→template<arithmetic T>                           \
   138→struct name final : adaptor_tag_t {              \
   139→	T& value;                                    \
   140→                                                 \
   141→    name(T& t) : value(t) {}                     \
   142→    name(T&& t) : value(t) {}                    \
   143→                                                 \
   144→	auto to() -> T {                             \
   145→		return func_to(value);                   \
   146→	}                                            \
   147→	auto from() -> T {                           \
   148→		return func_from(value);                 \
   149→	}                                            \
   150→};
   151→
   152→ENDIAN_ADAPTOR(be, native_to_big,    big_to_native)
   153→ENDIAN_ADAPTOR(le, native_to_little, little_to_native)
   154→
   155→struct storage_tag {};
   156→struct as_big_t final : storage_tag {};
   157→struct as_little_t final : storage_tag {};
   158→struct as_native_t final : storage_tag {};
   159→
   160→[[maybe_unused]] constexpr static as_big_t big {};
   161→[[maybe_unused]] constexpr static as_little_t little {};
   162→[[maybe_unused]] constexpr static as_native_t native {};
   163→
   164→inline auto storage_in(const arithmetic auto& value, as_native_t) {
   165→	return value;
   166→}
   167→
