   152→	 * @return Whether this container is capable of write seeking.
   153→	 */
   154→	bool can_write_seek() const override { 
   155→		return buffer_write_adaptor<buf_type>::can_write_seek();
   156→	};
   157→
   158→	/**
   159→	 * @brief Performs write seeking within the container.
   160→	 * 
   161→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   162→	 * @param offset The offset relative to the seek direction or the absolute value
   163→	 * when using absolute seeking.
   164→	 */
   165→	void write_seek(buffer_seek direction, std::size_t offset) override {
   166→		buffer_write_adaptor<buf_type>::write_seek(direction, offset);
   167→	};
   168→
   169→	/**
   170→	 * @brief Returns the size of the container.
   171→	 * 
   172→	 * @return The number of bytes of data available to read within the stream.
   173→	 */
   174→	std::size_t size() const override { 
   175→		return buffer_read_adaptor<buf_type>::size(); 
   176→	};
   177→
   178→	/**
   179→	 * @brief Whether the container is empty.
   180→	 * 
   181→	 * @return Returns true if the container is empty (has no data to be read).
   182→	 */
   183→	[[nodiscard]]
   184→	bool empty() const override {
   185→		return buffer_read_adaptor<buf_type>::read_offset()
   186→			== buffer_write_adaptor<buf_type>::write_offset();
   187→	}
   188→
   189→	/**
   190→	 * @brief Attempts to locate the provided value within the container.
   191→	 * 
   192→	 * @param value The value to locate.
   193→	 * 
   194→	 * @return The position of value or npos if not found.
   195→	 */
   196→	std::size_t find_first_of(std::byte val) const override { 
   197→		return buffer_read_adaptor<buf_type>::find_first_of(val);
   198→	}
