   135→		const auto offset = buffer_read_adaptor<buf_type>::read_offset();
   136→		auto buffer = buffer_write_adaptor<buf_type>::storage();
   137→		return reinterpret_cast<std::byte*>(buffer + offset)[index];
   138→	}
