    85→template<typename size_type, typename stream_type>
    86→constexpr auto varint_decode(stream_type& stream) -> size_type {
    87→	int shift { 0 };
    88→	size_type value { 0 };
    89→	std::uint8_t byte { 0 };
    90→
    91→	do {
    92→		byte = 0; // clear in case an error occurs
    93→		stream.get(&byte, 1);
    94→		value |= (static_cast<size_type>(byte & 0x7f) << shift);
    95→		shift += 7;
    96→	} while(byte & 0x80);
    97→
    98→	return value;
    99→}
   100→
   101→template<typename size_type, typename stream_type>
   102→constexpr auto varint_encode(stream_type& stream, size_type value) -> size_type {
   103→	size_type written = 0;
   104→
   105→	while(value > 0x7f) {
   106→		const std::uint8_t byte = (value & 0x7f) | 0x80;
   107→		stream.put(&byte, 1);
   108→		value >>= 7;
   109→		++written;
   110→	}
   111→
   112→	const std::uint8_t byte = value & 0x7f;
   113→	stream.put(&byte, 1);
   114→	return ++written;
   115→}
   116→
   117→template<decltype(auto) size>
   118→static constexpr auto generate_filled(const std::uint8_t value) {
   119→	std::array<std::uint8_t, size> target{};
   120→	std::ranges::fill(target, value);
   121→	return target;
   122→}
   123→
   124→// Returns true if there's any overlap between source and destination ranges
   125→[[maybe_unused]]
   126→static inline bool region_overlap(const void* src, std::size_t src_len,
   127→                                  const void* dst, std::size_t dst_len) {
   128→	const auto src_beg = std::bit_cast<std::uintptr_t>(src);
   129→	const auto src_end = src_beg + src_len;
   130→	const auto dst_beg = std::bit_cast<std::uintptr_t>(dst);
   131→	const auto dst_end = dst_beg + dst_len;
   132→	return src_beg < dst_end && dst_beg < src_end;
   133→}
