    58→template<typename T>
    59→concept has_reserve = 
    60→	requires(T t) {
    61→		{ t.reserve(typename T::size_type() ) } -> std::same_as<void>;
    62→};
    63→
    64→template<typename T>
    65→concept has_clear = 
    66→	requires(T t) {
    67→		{ t.clear() } -> std::same_as<void>;
    68→};
    69→
    70→template<typename T, typename U>
    71→concept has_shl_override =
    72→	requires(T t, U& u) {
    73→		{ t.operator<<(u) } -> std::same_as<U&>;
    74→};
    75→
    76→template<typename T, typename U>
    77→concept has_shr_override =
    78→	requires(T t, U& u) {
    79→		{ t.operator>>(u) } -> std::same_as<U&>;
    80→};
    81→
    82→template<typename T, typename U>
    83→concept has_serialise =
    84→	requires(T t, stream_write_adaptor<U>& u) {
    85→		{ t.serialise(u) } -> std::same_as<void>;
    86→};
    87→
    88→template<typename T, typename U>
    89→concept has_deserialise =
    90→	requires(T t, stream_read_adaptor<U>& u) {
    91→		{ t.serialise(u) } -> std::same_as<void>;
    92→};
    93→
    94→template<typename T>
    95→concept is_iterable =
    96→	requires(T t) {
    97→		t.begin(); t.end();
    98→};
