    22→template<byte_oriented buf_type>
    23→requires std::ranges::contiguous_range<buf_type>
    24→class buffer_write_adaptor : public buffer_write {
    25→	buf_type& buffer_;
    26→
    27→public:
    28→	buffer_write_adaptor(buf_type& buffer)
    29→		: buffer_(buffer) {
    30→		write_ = buffer.size();
    31→	}
    32→
    33→	buffer_write_adaptor(buf_type& buffer, init_empty_t)
    34→		: buffer_(buffer) {}
    35→
    36→	/**
    37→	 * @brief Write data to the container.
    38→	 * 
    39→	 * @note The source buffer must not overlap with the underlying buffer
    40→	 * being used by the buffer_adaptor.
    41→	 * 
    42→	 * @param source Pointer to the data to be written.
    43→	 */
    44→	void write(auto& source) {
    45→		write(&source, sizeof(source));
    46→	}
    47→
    48→	/**
    49→	 * @brief Write provided data to the container.
    50→	 *
    51→	 * @note The source buffer must not overlap with the underlying buffer
    52→	 * being used by the buffer_adaptor.
    53→	 * 
    54→	 * @param source Pointer to the data to be written.
    55→	 * @param length Number of bytes to write from the source.
    56→	 */
    57→	void write(const void* source, std::size_t length) override {
    58→		assert(source && !region_overlap(source, length, buffer_.data(), buffer_.size()));
    59→		const auto min_req_size = write_ + length;
    60→
    61→		if(buffer_.size() < min_req_size) [[likely]] {
    62→			if constexpr(has_resize_overwrite<buf_type>) {
    63→				buffer_.resize_and_overwrite(min_req_size, [](char*, std::size_t size) {
    64→					return size;
    65→				});
    66→			} else if constexpr(has_resize<buf_type>) {
    67→				buffer_.resize(min_req_size);
    68→			} else {
    69→				HEXI_THROW(buffer_overflow(free(), length, write_));
    70→			}
    71→		}
    72→
    73→		std::memcpy(buffer_.data() + write_, source, length);
    74→		write_ += length;
    75→	}
    76→
    77→	/**
    78→	 * @brief Reserves a number of bytes within the container for future use.
    79→	 * 
    80→	 * @note This is a non-binding request, meaning the buffer may not reserve
    81→	 * any additional space, such as in the case where it is not supported.
    82→	 *
    83→	 * @param length The number of bytes that the container should reserve.
    84→	 */
    85→	void reserve(const std::size_t length) override {
    86→		if constexpr(has_reserve<buf_type>) {
    87→			buffer_.reserve(length);
    88→		}
    89→	}
    90→
    91→	/**
    92→	 * @brief Determines whether this container can write seek.
    93→	 *
    94→	 * @return Whether this container is capable of write seeking.
    95→	 */
    96→	bool can_write_seek() const override {
    97→		return true;
    98→	}
    99→
   100→	/**
   101→	 * @brief Performs write seeking within the container.
   102→	 *
   103→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   104→	 * @param offset The offset relative to the seek direction or the absolute value
   105→	 * when using absolute seeking.
   106→	 */
   107→	void write_seek(const buffer_seek direction, const std::size_t offset) override {
   108→		switch(direction) {
   109→			case buffer_seek::sk_backward:
   110→				write_ -= offset;
   111→				break;
   112→			case buffer_seek::sk_forward:
   113→				write_ += offset;
   114→				break;
   115→			case buffer_seek::sk_absolute:
   116→				write_ = offset;
   117→		}
   118→	}
   119→
   120→	/**
   121→	 * @return Pointer to the underlying storage.
   122→	 */
   123→	auto storage() const {
   124→		return buffer_.data();
   125→	}
   126→
   127→	/**
   128→	 * @return Pointer to the underlying storage.
   129→	 */
   130→	auto storage() {
   131→		return buffer_.data();
   132→	}
   133→
   134→	/**
   135→	 * @return Pointer to the location within the buffer where the next write
   136→	 * will be made.
   137→	 */
   138→	auto write_ptr() {
   139→		return buffer_.data() + write_;
   140→	}
   141→
   142→	/**
   143→	 * @return Pointer to the location within the buffer where the next write
   144→	 * will be made.
   145→	 */
   146→	auto write_ptr() const {
   147→		return buffer_.data() + write_;
   148→	}
   149→
   150→	/**
   151→	* @return The current write offset.
   152→	*/
   153→	auto write_offset() const {
   154→		return write_;
   155→	}
   156→
   157→	/**
   158→	 * @brief Clear the underlying buffer and reset state.
   159→	 */
   160→	void clear() {
   161→		write_ = 0;
   162→
   163→		if constexpr(has_clear<buf_type>) {
   164→			buffer_.clear();
   165→		}
   166→	}
   167→
   168→	/**
   169→	* @brief Advances the write cursor.
   170→	* 
   171→	* @param size The number of bytes by which to advance the write cursor.
   172→	*/
   173→	void advance_write(std::size_t bytes) {
   174→		assert(buffer_.size() >= (write_ + bytes));
   175→		write_ += bytes;
   176→	}
   177→
   178→	/**
   179→	 * @brief The amount of free space.
   180→	 * 
   181→	 * @return The number of bytes of free space within the container.
   182→	 */
   183→	std::size_t free() const {
   184→		return buffer_.size() - write_;
   185→	}
   186→};
