   230→	 * @brief Retrieves a reference to the specified index within the container.
   231→	 * 
   232→	 * @param index The index within the container.
   233→	 * 
   234→	 * @return A reference to the value at the specified index.
   235→	 */
   236→	value_type& operator[](const size_type index) {
   237→		return read_ptr()[index];
   238→	}
   239→
   240→	/**
   241→	 * @brief Retrieves a reference to the specified index within the container.
   242→	 * 
   243→	 * @param index The index within the container.
   244→	 * 
   245→	 * @return A reference to the value at the specified index.
   246→	 */
   247→	const value_type& operator[](const size_type index) const {
   248→		return read_ptr()[index];
   249→	}
