    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a vector from the span data for the buffer_adaptor
    std::vector<uint8_t> vec(buffer.begin(), buffer.end());

    // Create a buffer_adaptor wrapping the vector
    hexi::buffer_adaptor adaptor(vec);

