    // Check available data
    auto available = adaptor.size();

    // Ensure we have enough data for the header
    if (available < sizeof(PacketHeader)) {
        return PacketHeader{0, 0, 0}; // Return empty header if insufficient data
    }

    // Create a binary_stream for zero-copy operations
    hexi::binary_stream<decltype(adaptor)> stream(adaptor);

    // Get a zero-copy view of the header using span
    auto header_span = stream.span<uint8_t>(sizeof(PacketHeader));

    // Extract header fields from the span
    PacketHeader header;

