    // Assuming little-endian byte order
    std::memcpy(&header.magic, header_span.data(), sizeof(uint32_t));
    std::memcpy(&header.version, header_span.data() + sizeof(uint32_t), sizeof(uint16_t));
    std::memcpy(&header.flags, header_span.data() + sizeof(uint32_t) + sizeof(uint16_t), sizeof(uint16_t));

    return header;
}
