    32→};
    33→
    34→template<typename T>
    35→concept arithmetic = std::integral<T> || std::floating_point<T>;
    36→
    37→template<typename T>
    38→concept byte_type = sizeof(T) == 1;
    39→
    40→template<typename T>
    41→concept byte_oriented = byte_type<typename T::value_type>;
    42→
    43→template<typename T>
    44→concept pod = std::is_standard_layout_v<T> && std::is_trivial_v<T>;
    45→
    46→template<typename T>
    47→concept has_resize_overwrite =
    48→	requires(T t) {
    49→		{ t.resize_and_overwrite(typename T::size_type(), [](char*, T::size_type) {}) } -> std::same_as<void>;
    50→};
    51→
    52→template<typename T>
    53→concept has_resize = 
    54→	requires(T t) {
    55→		{ t.resize(typename T::size_type() ) } -> std::same_as<void>;
    56→};
    57→
    58→template<typename T>
