   913→	 * @return A string view over data up to the provided terminator.
   914→	 * An empty string_view if a terminator is not found
   915→	 */
   916→	std::string_view view(value_type terminator = value_type(0)) requires contiguous<buf_type> {
   917→		const auto pos = buffer_.find_first_of(terminator);
   918→
   919→		if(pos == buf_type::npos) {
   920→			return {};
   921→		}
   922→
   923→		std::string_view view { reinterpret_cast<char*>(buffer_.read_ptr()), pos };
   924→
   925→		// no need to enforce bounds, we know there's enough data
   926→		buffer_.skip(pos + 1);
   927→		total_read_ += (pos + 1);
   928→		return view;
