   154→	/**
   155→	 * @brief Deserialises a string that was previously written with a
   156→	 * fixed-length prefix.
   157→	 * 
   158→	 * @param[out] adaptor std::string to hold the result.
   159→	 * 
   160→	 * @return Reference to the current stream.
   161→	 */
   162→	binary_stream_reader& operator>>(prefixed<std::string> adaptor) {
   163→		std::uint32_t size = 0;
   164→		*this >> endian::le(size);
   165→
   166→		if(state() != stream_state::ok) {
   167→			return *this;
   168→		}
   169→
   170→		STREAM_READ_BOUNDS_ENFORCE(size, *this);
   171→
   172→		adaptor->resize_and_overwrite(size, [&](char* strbuf, std::size_t size) {
   173→			buffer_.read(strbuf, size);
   174→			return size;
   175→		});
   176→
   177→		return *this;
   178→	}
   179→	
   180→	/**
   181→	 * @brief Deserialises a string that was previously written with a
   182→	 * variable-length prefix.
   183→	 * 
   184→	 * @param[out] adaptor std::string to hold the result.
   185→	 * 
   186→	 * @return Reference to the current stream.
   187→	 */
   188→	binary_stream_reader& operator>>(prefixed_varint<std::string> adaptor) {
   189→		const auto size = varint_decode<std::size_t>(*this);
   190→
   191→		// if an error was triggered during decode, we shouldn't reach here
   192→		if(state() != stream_state::ok) {
   193→			std::unreachable();
   194→		}
   195→
   196→		STREAM_READ_BOUNDS_ENFORCE(size, *this);
   197→
   198→		adaptor->resize_and_overwrite(size, [&](char* strbuf, std::size_t size) {
   199→			buffer_.read(strbuf, size);
   200→			return size;
   201→		});
   202→
   203→		return *this;
   204→	}
