    61→TEST(dynamic_buffer, reserve_fetch_consistency) {
    62→	hexi::dynamic_buffer<32> chain;
    63→	char text[] = "The quick brown fox jumps over the lazy dog";
    64→	const std::size_t text_len = sizeof(text);
    65→
    66→	chain.reserve(text_len);
    67→	ASSERT_EQ(text_len, chain.size()) << "Chain size is incorrect";
    68→
    69→	auto buffers = chain.fetch_buffers(text_len);
    70→	
    71→	// store text in the retrieved buffers
    72→	std::size_t offset = 0;
