     7→#pragma once
     8→
     9→#include <hexi/allocators/block_allocator.h>
    10→#include <type_traits>
    11→#include <utility>
    12→#include <cassert>
    13→#include <cstddef>
    14→#include <cstdint>
    15→
    16→#ifndef NDEBUG
    17→#define HEXI_DEBUG_ALLOCATORS
    18→#endif
    19→
    20→namespace hexi {
    21→
    22→struct safe_entrant {};
    23→struct no_ref_counting {};
    24→
    25→struct unsafe_entrant : safe_entrant {};
    26→struct ref_counting : no_ref_counting {};
    27→
    28→template<typename _ty,
    29→	std::size_t _elements,
    30→	std::derived_from<no_ref_counting> ref_count_policy = no_ref_counting,
    31→	std::derived_from<safe_entrant> entrant_policy = safe_entrant
    32→>
    33→class tls_block_allocator final {
    34→	using allocator_type = block_allocator<_ty, _elements>;
    35→
    36→	using ref_count = std::conditional_t<
    37→		std::is_same_v<ref_count_policy, ref_counting>, int, std::monostate
    38→	>;
    39→
    40→	using tls_handle_cache = std::conditional_t<
    41→		std::is_same_v<entrant_policy, unsafe_entrant>, allocator_type*, std::monostate
    42→	>;
    43→
    44→	static inline thread_local std::unique_ptr<allocator_type> allocator_;
    45→	static inline thread_local ref_count ref_count_{};
    46→
    47→	[[no_unique_address]] tls_handle_cache cached_handle_{};
    48→
    49→	// Compiler will optimise calls to this out when using unsafe_entrant
    50→	inline void initialise() {
    51→		if constexpr(std::is_same_v<entrant_policy, safe_entrant>) {
    52→			if(!allocator_) {
    53→				allocator_ = std::make_unique<allocator_type>();
    54→			}
    55→		}
    56→	}
    57→
    58→	inline allocator_type* allocator_handle() {
    59→		if constexpr(std::is_same_v<entrant_policy, unsafe_entrant>) {
    60→			return cached_handle_;
    61→		} else {
    62→			return allocator_.get();
    63→		}
    64→	}
    65→
    66→public:
    67→#ifdef HEXI_DEBUG_ALLOCATORS
    68→	std::size_t total_allocs = 0;
    69→	std::size_t total_deallocs = 0;
    70→	std::size_t active_allocs = 0;
    71→#endif
    72→
    73→	tls_block_allocator() {
    74→		thread_enter();
    75→	}
    76→
    77→	/*
    78→	 * When used in conjunction with unsafe_entrant, allows the owning object
    79→	 * to be executed on another thread without paying for checks on every
    80→	 * allocation
    81→	 * 
    82→	 * @note If ref counting is enabled, the count will be incremented.
    83→	 */
    84→	inline void thread_enter() {
    85→		if(!allocator_) {
    86→			allocator_ = std::make_unique<allocator_type>();
    87→		}
    88→
    89→		if constexpr(std::is_same_v<entrant_policy, unsafe_entrant>) {
    90→			cached_handle_ = allocator_.get();
    91→		}
    92→
    93→		if constexpr(std::is_same_v<ref_count_policy, ref_counting>) {
    94→			++ref_count_;
    95→		}
    96→	}
    97→
    98→	/*
    99→	 * When used in conjunction with unsafe_entrant, signals that the current
   100→	 * thread not make further calls into the allocator.
   101→	 * 
   102→	 * @note If ref counting is enabled, the count will be decremented.
   103→	 */
   104→	inline void thread_exit() {
   105→		if constexpr(std::is_same_v<ref_count_policy, ref_counting>) {
   106→			assert(ref_count_);
   107→
   108→			--ref_count_;
   109→
   110→			if(ref_count_ == 0) {
   111→				allocator_.reset();
   112→			}
   113→		}
   114→	}
   115→
   116→	/*
   117→	 * @brief Allocates and constructs an object.
   118→	 * 
   119→	 * @tparam Args Variadic arguments to be forwarded to the object's constructor.
   120→	 * 
   121→	 * @return Pointer to the allocated object.
   122→	 */
   123→	template<typename ...Args>
   124→	[[nodiscard]] inline _ty* allocate(Args&&... args) {
   125→		/*
   126→		 * When safe_entrant is set, need to do this here & in ctor unless
   127→		 * we can be 100% sure that any object using the allocator is created
   128→		 * on the same thread that ends up using it.
   129→		 */
   130→		initialise();
   131→
   132→#ifdef HEXI_DEBUG_ALLOCATORS
   133→		++total_allocs;
   134→		++active_allocs;
   135→#endif
   136→		return allocator_handle()->allocate(std::forward<Args>(args)...);
   137→	}
   138→
   139→	/*
   140→	 * @brief Deallocates and destructs an object.
   141→	 * 
   142→	 * @param t The object to be deallocated.
   143→	 */
   144→	inline void deallocate(_ty* t) {
   145→		assert(t);
   146→
   147→#ifdef HEXI_DEBUG_ALLOCATORS
   148→		++total_deallocs;
   149→		--active_allocs;
   150→#endif
   151→		allocator_handle()->deallocate(t);
   152→	}
   153→
   154→#ifdef HEXI_DEBUG_ALLOCATORS
   155→	auto allocator() {
   156→		initialise();
   157→		return allocator_handle();
   158→	}
   159→#endif
   160→
   161→	~tls_block_allocator() {
   162→		thread_exit();
   163→
   164→#ifdef HEXI_DEBUG_ALLOCATORS
   165→		assert(active_allocs == 0);
   166→#endif
   167→	}
   168→};
   169→
   170→} // hexi
