     7→#pragma once
     8→
     9→#include <array>
    10→#include <memory>
    11→#include <new>
    12→#include <thread>
    13→#include <type_traits>
    14→#include <utility>
    15→#include <cassert>
    16→#include <cstddef>
    17→#include <cstdint>
    18→
