    30→template<std::size_t block_size, byte_type storage_type = std::byte>
    31→struct intrusive_storage final {
    32→	using value_type = storage_type;
    33→	using offset_type = std::remove_const_t<decltype(block_size)>;
    34→
    35→	offset_type read_offset = 0;
    36→	offset_type write_offset = 0;
    37→	intrusive_node node {};
    38→	std::array<value_type, block_size> storage;
    39→
    40→	/**
    41→	 * @brief Clear the container.
    42→	 * 
    43→	 * Resets the read and write offsets, does not explicitly
    44→	 * erase the data contained within the buffer but should
    45→	 * be treated as such.
    46→	 */
    47→	void clear() {
    48→		read_offset = 0;
    49→		write_offset = 0;
    50→	}
    51→
    52→	/**
    53→	 * @brief Write provided data to the container.
    54→	 * 
    55→	 * If the container size is lower than requested number of bytes,
    56→	 * the request will be capped at the number of bytes available.
    57→	 * 
    58→	 * @note The source buffer must not overlap with the underlying buffer.
    59→	 * 
    60→	 * @param source Pointer to the data to be written.
    61→	 * @param length Number of bytes to write from the source.
    62→	 * 
    63→	 * @return The number of bytes copied, which may be less than requested.
    64→	 */
    65→	std::size_t write(const auto source, std::size_t length) {
    66→		assert(!region_overlap(source, length, storage.data(), storage.size()));
    67→		std::size_t write_len = block_size - write_offset;
    68→
    69→		if(write_len > length) {
    70→			write_len = length;
    71→		}
    72→
    73→		std::memcpy(storage.data() + write_offset, source, write_len);
    74→		write_offset += static_cast<offset_type>(write_len);
    75→		return write_len;
    76→	}
    77→
    78→	/**
    79→	 * @brief Copies a number of bytes to the provided buffer but without
    80→	 * advancing the read cursor.
    81→	 * 
    82→	 * If the container size is lower than requested number of bytes,
    83→	 * the request will be capped at the number of bytes available.
    84→	 * 
    85→	 * @note The destination buffer must not overlap with the underlying buffer.
    86→	 * 
    87→	 * @param[out] destination The buffer to copy the data to.
    88→	 * @param length The number of bytes to copy.
    89→	 * 
    90→	 * @return The number of bytes copied, which may be less than requested.
    91→	 */
    92→	std::size_t copy(auto destination, const std::size_t length) const {
    93→		assert(!region_overlap(storage.data(), storage.size(), destination, length));
    94→		std::size_t read_len = block_size - read_offset;
    95→
    96→		if(read_len > length) {
    97→			read_len = length;
    98→		}
    99→
   100→		std::memcpy(destination, storage.data() + read_offset, read_len);
   101→		return read_len;
   102→	}
   103→
   104→	/**
   105→	 * @brief Reads a number of bytes to the provided buffer.
   106→	 * 
   107→	 * If the container size is lower than requested number of bytes,
   108→	 * the request will be capped at the number of bytes available.
   109→	 * 
   110→	 * @note The destination buffer must not overlap with the underlying buffer.
   111→	 * 
   112→	 * @param length The number of bytes to skip.
   113→	 * @param[out] destination The buffer to copy the data to.
   114→	 * @param allow_optimise Whether the buffer can reuse its space where possible.
   115→	 * 
   116→	 * @return The number of bytes read, which may be less than requested.
   117→	 */
   118→	std::size_t read(auto destination, const std::size_t length, const bool allow_optimise = false) {
   119→		std::size_t read_len = copy(destination, length);
   120→		read_offset += static_cast<offset_type>(read_len);
   121→
   122→		if(read_offset == write_offset && allow_optimise) {
   123→			clear();
   124→		}
   125→
   126→		return read_len;
   127→	}
   128→
   129→	/**
   130→	 * @brief Skip over a number of bytes.
   131→	 *
   132→	 * Skips over a number of bytes in the container. This should be used
   133→	 * if the container holds data that you don't care about but don't want
   134→	 * to have to read it to another buffer to access data beyond it.
   135→	 * 
   136→	 * If the container size is lower than requested number of bytes,
   137→	 * the request will be capped at the number of bytes available.
   138→	 * 
   139→	 * @param length The number of bytes to skip.
   140→	 * @param allow_optimise Whether the buffer can reuse its space where possible.
   141→	 * 
   142→	 * @return The number of bytes skipped, which may be less than requested.
   143→	 */
   144→	std::size_t skip(const std::size_t length, const bool allow_optimise = false) {
   145→		std::size_t skip_len = block_size - read_offset;
   146→
   147→		if(skip_len > length) {
   148→			skip_len = length;
   149→		}
   150→
   151→		read_offset += static_cast<offset_type>(skip_len);
   152→
   153→		if(read_offset == write_offset && allow_optimise) {
   154→			clear();
   155→		}
   156→
   157→		return skip_len;
   158→	}
   159→
   160→	/**
   161→	 * @brief Returns the size of the container.
   162→	 * 
   163→	 * @return The number of bytes available to read within the container.
   164→	 */
   165→	std::size_t size() const {
   166→		return write_offset - read_offset;
   167→	}
   168→
   169→	/**
   170→	 * @brief The amount of free space.
   171→	 * 
   172→	 * @return The number of bytes of free space within the container.
   173→	 */
   174→	std::size_t free() const {
   175→		return block_size - write_offset;
   176→	}
   177→
   178→	/**
   179→	 * @brief Performs write seeking within the container.
   180→	 * 
   181→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   182→	 * @param offset The offset relative to the seek direction or the absolute value
   183→	 * when using absolute seeking.
   184→	 */
   185→	void write_seek(const buffer_seek direction, const std::size_t offset) {
   186→		switch(direction) {
   187→			case buffer_seek::sk_absolute:
   188→				write_offset = offset;
   189→				break;
   190→			case buffer_seek::sk_backward:
   191→				write_offset -= static_cast<offset_type>(offset);
   192→				break;
   193→			case buffer_seek::sk_forward:
   194→				write_offset += static_cast<offset_type>(offset);
   195→				break;
   196→		}
   197→	}
   198→
   199→	/**
   200→	 * @brief Advances the write cursor.
   201→	 * 
   202→	 * If the requested number of bytes exceeds the free space, the
   203→	 * request will be capped at the amount of free space.
   204→	 * 
   205→	 * @param size The number of bytes by which to advance the write cursor.
   206→	 * 
   207→	 * @return The number of bytes the write cursor was advanced by, which
   208→	 * may be less than requested.
   209→	 */
   210→	std::size_t advance_write(std::size_t size) {
   211→		const auto remaining = free();
   212→
   213→		if(remaining < size) {
   214→			size = remaining;
   215→		}
   216→
   217→		write_offset += static_cast<offset_type>(size);
   218→		return size;
   219→	}
