#include <hexi/file_buffer.h>
#include <filesystem>

size_t get_file_readable_size(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        // Error occurred while opening/initializing the file
        return 0;
    }

    return buffer.size();
}

bool is_file_buffer_valid(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);

    // The error() method returns true if an error occurred
    // We want to return true if valid (no error), so we negate it
    return !buffer.error();

    // Alternative: Use the bool operator which returns true if valid
    // return static_cast<bool>(buffer);
}
