    37→	/**
    38→	* @brief Explicitly close the underlying file handle.
    39→	* 
    40→	* This function will be called by the object's destructor
    41→	* and does not need to be called explicitly.
    42→	* 
    43→	* @note Idempotent.
    44→	*/
    45→	void close() {
    46→		if(file_) {
    47→			std::fclose(file_);
    48→			file_ = nullptr;
    49→		}
    50→	}
    51→
    52→public:
    53→	file_buffer(const std::filesystem::path& path)
    54→		: file_buffer(path.string().c_str()) { }
    55→
    56→	file_buffer(const char* path) {
    57→		file_ = std::fopen(path, "a+b");
    58→		
    59→		if(!file_) {
    60→			error_ = true;
    61→			return;
    62→		}
    63→		
    64→		if(std::fseek(file_, 0, SEEK_END)) {
    65→			error_ = true;
    66→			return;
    67→		}
    68→
    69→		write_ = std::ftell(file_);
    70→
    71→		if(write_ == -1) {
    72→			error_ = true;
    73→		}
    74→	}
    75→
    76→	file_buffer(file_buffer&& rhs) noexcept
    77→		: file_(rhs.file_),
    78→		  read_(rhs.read_),
    79→		  write_(rhs.write_),
    80→		  error_(rhs.error_) {
    81→		rhs.file_ = nullptr;
    82→	}
    83→
    84→	file_buffer& operator=(file_buffer&& rhs) noexcept {
    85→		std::exchange(file_, rhs.file_);
    86→		read_ = rhs.read_;
    87→		write_ = rhs.write_;
    88→		error_ = rhs.error_;
    89→		return *this;
    90→	}
    91→
    92→	file_buffer& operator=(const file_buffer&) = delete;
    93→	file_buffer(const file_buffer&) = delete;
    94→
    95→	~file_buffer() {
    96→		close();
    97→	}
