   203→
   204→	/**
   205→	 * @brief Serialises an object that provides a serialise function:
   206→	 * void serialise(auto& stream);
   207→	 * 
   208→	 * @param object The object to be serialised.
   209→	 */
   210→	void serialise(auto&& object) requires writeable<buf_type> {
   211→		stream_write_adaptor adaptor(*this);
   212→		object.serialise(adaptor);
   213→	}
   214→
   215→	/**
   216→	 * @brief Serialises an object that provides a serialise function:
   217→	 * void serialise(auto& stream);
   218→	 * 
   219→	 * @param data The object to be serialised.
   220→	 * 
   221→	 * @return Reference to the current stream.
   222→	 */
   223→	template<typename T>
   224→	requires has_serialise<T, binary_stream>
   225→	binary_stream& operator<<(T& data) requires writeable<buf_type> {
   226→		serialise(data);
   227→		return *this;
   228→	}
   229→
   230→	/**
   231→	 * @brief Serialises an object that provides a serialise function:
   232→	 * auto& operator<<(auto& stream);
   233→	 * 
   234→	 * @param data The object to be serialised.
   235→	 * 
   236→	 * @return Reference to the current stream.
   237→	 */
   238→	binary_stream& operator<<(const has_shl_override<binary_stream> auto& data)
   239→	requires writeable<buf_type> {
   240→		return *this << data;
   241→	}
   242→
   243→	/**
   244→	 * @brief Serialises an arithmetic type with the requested byte order.
   245→	 * 
   246→	 * @param adaptor An endian adaptor.
   247→	 * 
   248→	 * @return Reference to the current stream.
   249→	 */
   250→	template<std::derived_from<endian::adaptor_tag_t> endian_func>
   251→	binary_stream& operator<<(endian_func adaptor) requires writeable<buf_type> {
   252→		const auto converted = adaptor.to();
   253→		write(&converted, sizeof(converted));
   254→		return *this;
   255→	}
   256→
   257→	/**
   258→	 * @brief Serialises an arithmetic type with the default byte order.
   259→	 * 
   260→	 * @param data Reference to the type to be serialised.
   261→	 * 
   262→	 * @return Reference to the current stream.
   263→	 */
   264→	binary_stream& operator<<(const arithmetic auto& data) requires writeable<buf_type> {
   265→		const auto converted = endian::storage_in(data, byte_order);
   266→		write(&converted, sizeof(converted));
   267→		return *this;
   268→	}
