   323→	/**
   324→	 * @brief Serialises a string, string_view or any type providing data()
   325→	 * and a size() member functions.
   326→	 * 
   327→	 * @tparam T The type.
   328→	 * @param adaptor raw adaptor referencing the type to be serialised.
   329→	 * 
   330→	 * @return Reference to the current stream.
   331→	 */
   332→	template<typename T>
   333→	binary_stream& operator<<(raw<T> adaptor) requires writeable<buf_type> {
   334→		write(adaptor->data(), adaptor->size());
