   242→	/**
   243→	 * @brief Write data to the container.
   244→	 * 
   245→	 * @param source Pointer to the data to be written.
   246→	 */
   247→	void write(const auto& source) {
   248→		write(&source, sizeof(source));
   249→	}
   250→
   251→	/**
   252→	 * @brief Write provided data to the container.
   253→	 * 
   254→	 * @note The source buffer address must not belong to the static_buffer.
   255→	 * 
   256→	 * @param source Pointer to the data to be written.
   257→	 * @param length Number of bytes to write from the source.
   258→	 */
   259→	void write(const void* source, size_type length) {
   260→		assert(!region_overlap(source, length, buffer_.data(), buffer_.size()));
   261→
   262→		if(free() < length) {
   263→			HEXI_THROW(buffer_overflow(length, write_, free()));
   264→		}
   265→
   266→		std::memcpy(write_ptr(), source, length);
   267→		write_ += length;
   268→	}
   269→
   270→	/**
   271→	 * @brief Performs write seeking within the container.
   272→	 * 
   273→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   274→	 * @param offset The offset relative to the seek direction or the absolute value
   275→	 * when using absolute seeking.
   276→	 */
   277→	void write_seek(const buffer_seek direction, const size_type offset) {
   278→		switch(direction) {
   279→			case buffer_seek::sk_backward:
   280→				write_ -= offset;
   281→				break;
   282→			case buffer_seek::sk_forward:
   283→				write_ += offset;
   284→				break;
   285→			case buffer_seek::sk_absolute:
   286→				write_ = offset;
   287→		}
   288→	}
