    66→	requires(T t) {
    67→		{ t.clear() } -> std::same_as<void>;
    68→};
    69→
    70→template<typename T, typename U>
    71→concept has_shl_override =
    72→	requires(T t, U& u) {
    73→		{ t.operator<<(u) } -> std::same_as<U&>;
    74→};
    75→
    76→template<typename T, typename U>
    77→concept has_shr_override =
    78→	requires(T t, U& u) {
    79→		{ t.operator>>(u) } -> std::same_as<U&>;
    80→};
