   453→
   454→	/**
   455→	 * @brief Skip over a number of bytes.
   456→	 *
   457→	 * Skips over a number of bytes from the stream. This should be used
   458→	 * if the stream holds data that you don't care about but don't want
   459→	 * to have to read it to another buffer to access data beyond it.
   460→	 * 
   461→	 * @param length The number of bytes to skip.
   462→	 */
   463→	void skip(std::size_t length) {
   464→		STREAM_READ_BOUNDS_ENFORCE(length, void());
   465→		buffer_.skip(length);
   466→	}
