   124→TEST(binary_stream_pmc, read_write_vector) {
   125→	hexi::dynamic_buffer<32> buffer;
   126→	hexi::pmc::binary_stream stream(buffer);
   127→
   128→	const auto time = std::chrono::system_clock::now().time_since_epoch();
   129→	const unsigned int seed = static_cast<unsigned int>(time.count());
   130→	std::srand(seed);
   131→
   132→	std::vector<int> in(std::rand() % 200);
   133→	std::ranges::iota(in, std::rand() % 100);
   134→	std::ranges::shuffle(in, std::default_random_engine(seed));
   135→
   136→	stream.put(in.begin(), in.end());
   137→
   138→	ASSERT_EQ(stream.size(), in.size() * sizeof(int));
   139→
   140→	// read the integers back one by one, making sure they
   141→	// match the expected value
   142→	for(auto value : in) {
   143→		int output = -1;
   144→		stream >> output;
   145→		ASSERT_EQ(output, value);
   146→	}
   147→
   148→	stream.put(in.begin(), in.end());
   149→	std::vector<int> out(in.size());
   150→
   151→	// read the integers to an output buffer and compare both
   152→	stream.get(out.begin(), out.end());
   153→	ASSERT_EQ(in, out);
   154→	ASSERT_EQ(stream.state(), hexi::stream_state::ok)
   155→		<< "Unexpected stream state";
   156→}
