    29→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    30→		} else if constexpr(std::is_same_v<type, double>) {
    31→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    32→		} else {
    33→			value = std::byteswap(value);
    34→		}
    35→	}
    36→
    37→	return value;
    38→}
