   368→	/**
   369→	 * @brief Read data from the stream into the provided destination argument.
   370→	 * 
   371→	 * @param[out] dest The destination buffer.
   372→	 * @param count The number of elements to be read into the destination.
   373→	 */
   374→	template<typename T>
   375→	void get(T* dest, std::size_t count) {
   376→		assert(dest);
   377→		const auto read_size = count * sizeof(T);
   378→		SAFE_READ(dest, read_size, void());
   379→	}
