    24→constexpr auto conditional_reverse(arithmetic auto value, std::endian from, std::endian to) {
    25→	using type = decltype(value);
    26→
    27→	if(from != to) {
    28→		if constexpr(std::is_same_v<type, float>) {
    29→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    30→		} else if constexpr(std::is_same_v<type, double>) {
    31→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    32→		} else {
    33→			value = std::byteswap(value);
    34→		}
    35→	}
    36→
    37→	return value;
    38→}
    39→
    40→template<std::endian from, std::endian to>
    41→constexpr auto conditional_reverse(arithmetic auto value) {
    42→	using type = decltype(value);
    43→
    44→	if constexpr(from != to) {
    45→		if constexpr(std::is_same_v<type, float>) {
    46→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint32_t>(value)));
    47→		} else if constexpr(std::is_same_v<type, double>) {
    48→			value = std::bit_cast<type>(std::byteswap(std::bit_cast<std::uint64_t>(value)));
    49→		} else {
    50→			value = std::byteswap(value);
    51→		}
    52→	}
    53→
    54→	return value;
    55→}
    56→
    57→constexpr auto little_to_native(arithmetic auto value) {
    58→	return conditional_reverse<std::endian::little, std::endian::native>(value);
    59→}
    60→
    61→constexpr auto big_to_native(arithmetic auto value) {
    62→	return conditional_reverse<std::endian::big, std::endian::native>(value);
    63→}
    64→
    65→constexpr auto native_to_little(arithmetic auto value) {
    66→	return conditional_reverse<std::endian::native, std::endian::little>(value);
    67→}
    68→
    69→constexpr auto native_to_big(arithmetic auto value) {
    70→	return conditional_reverse<std::endian::native, std::endian::big>(value);
    71→}
