#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <hexi/shared.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>

void write_container_to_stream(pmc::binary_stream_writer& writer, const std::vector<uint32_t>& container) {
    // Write using the prefixed adaptor which adds a uint32_t count prefix
    writer << hexi::prefixed(container);
}

std::vector<uint32_t> read_container_from_stream(pmc::binary_stream_reader& reader) {
    // Read using the prefixed adaptor which reads the count first, then elements
    std::vector<uint32_t> container;
    reader >> hexi::prefixed(container);
    return container;
}
```

The `prefixed` adaptor automatically handles writing/reading the container count (as a little-endian uint32_t) followed by the elements.

