#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstddef>
#include <cstdint>

bool check_can_write_seek(pmc::buffer_adaptor<std::vector<std::byte>>& buffer) {
    return buffer.can_write_seek();
}

void seek_write_position(pmc::buffer_adaptor<std::vector<std::byte>>& buffer, buffer_seek direction, std::size_t offset) {
    buffer.write_seek(direction, offset);
}

void update_header_at_position(pmc::buffer_adaptor<std::vector<std::byte>>& buffer, uint32_t header_value) {
    // Save current write position
    std::size_t current_position = buffer.write_offset();

    // Write header placeholder at the beginning
    buffer.write_seek(hexi::buffer_seek::sk_absolute, 0);
    buffer.write(&header_value, sizeof(header_value));

    // Seek back to original position to continue writing body
    buffer.write_seek(hexi::buffer_seek::sk_absolute, current_position);
}
```

**Key dependencies explained:**
- `buffer_seek::sk_absolute` - seek to absolute position
- `buffer_seek::sk_backward` - seek backward by offset
- `buffer_seek::sk_forward` - seek forward by offset
- `can_write_seek()` - returns true if buffer supports write seeking
- `write_seek(direction, offset)` - performs the actual seeking operation
- `write_offset()` - returns current write cursor position
- `write()` - writes data to buffer at current position

