#include "Hexi/include/hexi/pmc/buffer_adaptor.h"

void clear_buffer(pmc::buffer_adaptor<std::vector<std::byte>>& buffer) {
    buffer.clear();
}

void conditional_clear_buffer(pmc::buffer_adaptor<std::vector<std::byte>>& buffer) {
    // Note: conditional_clear() is a private method in buffer_adaptor
    // We need to implement the same logic publicly:
    // Check if read_ptr() == write_ptr(), then call clear()

    // Since conditional_clear is private, we need to check if the buffer is empty
    // which internally means read and write pointers are at the same position
    if (buffer.empty()) {
        buffer.clear();
    }
}
```

**Note:** The `conditional_clear()` method is private in `pmc::buffer_adaptor`, so it cannot be called directly from outside the class. The implementation above uses the public `empty()` method which checks if `read_ == write_`, which is equivalent to the condition used in `conditional_clear()`.

