   544→	/**
   545→	 * @brief Deserialises a string that was previously written with a
   546→	 * fixed-length prefix.
   547→	 * 
   548→	 * @param[out] adaptor std::string_view to hold the result.
   549→	 * 
   550→	 * @note The string_view's lifetime is tied to that of the underlying
   551→	 * buffer. You should not make any further writes to the buffer
   552→	 * unless you know it will not cause the data to be overwritten or
   553→	 * relocated (std::vector).
   554→	 * 
   555→	 * @return Reference to the current stream.
   556→	 */
   557→	binary_stream& operator>>(prefixed<std::string_view> adaptor) {
   558→		std::uint32_t size = 0;
   559→		*this >> endian::le(size);
   560→
   561→		if(state_ != stream_state::ok) {
   562→			return *this;
   563→		}
   564→
   565→		adaptor.str = std::string_view { span<char>(size) };
   566→		return *this;
   567→	}
