   620→	/**
   621→	 * @brief Deserialises a string that was previously written with a
   622→	 * null terminator.
   623→	 * 
   624→	 * @param[out] adaptor std::string to hold the result.
   625→	 * 
   626→	 * @return Reference to the current stream.
   627→	 */
   628→	binary_stream& operator>>(null_terminated<std::string> adaptor) {
   629→		auto pos = buffer_.find_first_of(value_type(0));
   630→
   631→		if(pos == buf_type::npos) {
   632→			adaptor->clear();
   633→			return *this;
   634→		}
   635→
   636→		STREAM_READ_BOUNDS_ENFORCE(pos + 1, *this); // include null terminator
   637→
   638→		adaptor->resize_and_overwrite(pos, [&](char* strbuf, std::size_t size) {
   639→			buffer_.read(strbuf, pos);
   640→			return size;
   641→		});
   642→
   643→		// no need to enforce bounds, we know there's enough data
   644→		buffer_.skip(1); // skip null terminator
   645→		return *this;
   646→	}
   647→
   648→	/**
   649→	 * @brief Deserialises a string that was previously written with a
   650→	 * null terminator.
   651→	 * 
   652→	 * @param[out] adaptor std::string_view to hold the result.
   653→	 * 
   654→	 * @note The string_view's lifetime is tied to that of the underlying
   655→	 * buffer. You should not make any further writes to the buffer
   656→	 * unless you know it will not cause the data to be overwritten (i.e.
   657→	 * buffer adaptor with optimise disabled).
   658→	 * 
   659→	 * @return Reference to the current stream.
   660→	 */
