    13→template<typename stream_type>
    14→class stream_read_adaptor final {
    15→	stream_type& _stream;
    16→
    17→public:
    18→	stream_read_adaptor(stream_type& stream) 
    19→		: _stream(stream) {}
    20→
    21→	void operator&(auto&& arg) {
    22→		_stream >> arg;
    23→	}
    24→
    25→	template<typename ...Ts>
    26→	void operator()(Ts&&... args) {
    27→		(_stream >> ... >> args);
    28→	}
    29→
    30→	template<typename ...Ts>
    31→	void forward(Ts&&... args) {
    32→		_stream.get(std::forward<Ts>(args)...);
    33→	}
    34→};
    35→
    36→template<typename stream_type>
    37→class stream_write_adaptor final {
    38→	stream_type& _stream;
    39→
    40→public:
    41→	stream_write_adaptor(stream_type& stream) 
    42→		: _stream(stream) {}
    43→
    44→	void operator&(auto&& arg) {
    45→		_stream << arg;
    46→	}
    47→
    48→	template<typename ...Ts>
    49→	void operator()(Ts&&... args) {
    50→		(_stream << ... << args);
    51→	}
    52→
    53→	template<typename ...Ts>
    54→	void forward(Ts&&... args) {
    55→		_stream.put(std::forward<Ts>(args)...);
    56→	}
    57→};
