    61→constexpr auto big_to_native(arithmetic auto value) {
    62→	return conditional_reverse<std::endian::big, std::endian::native>(value);
    63→}
    64→
    65→constexpr auto native_to_little(arithmetic auto value) {
    66→	return conditional_reverse<std::endian::native, std::endian::little>(value);
    67→}
