   114→		std::memcpy(destination, read_ptr(), length);
   115→	}
   116→
   117→	/**
   118→	 * @brief Skip over a number of bytes.
   119→	 * 
   120→	 * Skips over a number of bytes from the container. This should be used
   121→	 * if the container holds data that you don't care about but don't want
   122→	 * to have to read it to another buffer to access data beyond it.
   123→	 * 
   124→	 * @param length The number of bytes to skip.
   125→	 */
   126→	void skip(size_type length) {
   127→		read_ += length;
   128→
   129→		if constexpr(space_optimise) {
   130→			if(read_ == write_) {
   131→				read_ = write_ = 0;
   132→			}
   133→		}
   134→	}
   135→
   136→	/**
   137→	 * @brief Write data to the container.
   138→	 * 
   139→	 * @note The source buffer must not overlap with the underlying buffer
   140→	 * being used by the buffer_adaptor.
   141→	 * 
   142→	 * @param source Pointer to the data to be written.
   143→	 */
   144→	void write(const auto& source) {
   145→		write(&source, sizeof(source));
   146→	}
   147→
   148→	/**
   149→	 * @brief Write provided data to the container.
   150→	 * 
   151→	 * @note The source buffer must not overlap with the underlying buffer
   152→	 * being used by the buffer_adaptor.
   153→	 * 
   154→	 * @param source Pointer to the data to be written.
   155→	 * @param length Number of bytes to write from the source.
   156→	 */
   157→	void write(const void* source, size_type length) {
   158→		assert(source && !region_overlap(source, length, buffer_.data(), buffer_.size()));
   159→		const auto min_req_size = write_ + length;
   160→
   161→		if(buffer_.size() < min_req_size) [[likely]] {
   162→			if constexpr(has_resize_overwrite<buf_type>) {
   163→				buffer_.resize_and_overwrite(min_req_size, [](char*, size_type size) {
   164→					return size;
   165→				});
   166→			} else if constexpr(has_resize<buf_type>) {
   167→				buffer_.resize(min_req_size);
   168→			} else {
   169→				HEXI_THROW(buffer_overflow(length, write_, free()));
   170→			}
   171→		}
   172→
   173→		std::memcpy(write_ptr(), source, length);
   174→		write_ += length;
   175→	}
