   191→	/**
   192→	 * @brief Attempts to locate the provided value within the container.
   193→	 * 
   194→	 * @param value The value to locate.
   195→	 * 
   196→	 * @return The position of value or npos if not found.
   197→	 */
   198→	size_type find_first_of(value_type val) const {
   199→		const auto data = read_ptr();
   200→
   201→		for(size_type i = 0, j = size(); i < j; ++i) {
   202→			if(data[i] == val) {
   203→				return i;
   204→			}
   205→		}
   206→
   207→		return npos;
   208→	}
