    36→	static constexpr auto npos { static_cast<size_type>(-1) };
    37→	
    38→	static_buffer() = default;
    39→
    40→	template<typename... T> 
    41→	static_buffer(T&&... vals) : buffer_{ std::forward<T>(vals)... } {
    42→		write_ = sizeof... (vals);
    43→	}
    44→
    45→	static_buffer(static_buffer&& rhs) = default;
    46→	static_buffer& operator=(static_buffer&&) = default;
    47→	static_buffer& operator=(const static_buffer&) = default;
    48→	static_buffer(const static_buffer&) = default;
    49→
    50→	/**
    51→	 * @brief Reads a number of bytes to the provided buffer.
    52→	 * 
    53→	 * @param destination The buffer to copy the data to.
    54→	 */
    55→	template<typename T>
    56→	void read(T* destination) {
    57→		read(destination, sizeof(T));
    58→	}
    59→
    60→	/**
    61→	 * @brief Reads a number of bytes to the provided buffer.
    62→	 * 
    63→	 * @param destination The buffer to copy the data to.
    64→	 * @param length The number of bytes to read into the buffer.
    65→	 */
    66→	void read(void* destination, size_type length) {
    67→		copy(destination, length);
    68→		read_ += length;
    69→
    70→		if(read_ == write_) {
    71→			read_ = write_ = 0;
    72→		}
    73→	}
    74→
    75→	/**
    76→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    77→	 * the read cursor.
    78→	 * 
    79→	 * @param destination The buffer to copy the data to.
    80→	 */
    81→	template<typename T>
    82→	void copy(T* destination) const {
    83→		copy(destination, sizeof(T));
    84→	}
    85→
    86→	/**
    87→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    88→	 * the read cursor.
    89→	 * 
    90→	 * @note The destination buffer address must not belong to the static_buffer.
    91→	 * 
    92→	 * @param destination The buffer to copy the data to.
    93→	 * @param length The number of bytes to copy.
    94→	 */
    95→	void copy(void* destination, size_type length) const {
    96→		assert(!region_overlap(buffer_.data(), buffer_.size(), destination, length));
    97→
    98→		if(length > size()) {
    99→			HEXI_THROW(buffer_underrun(length, read_, size()));
   100→		}
   101→
   102→		std::memcpy(destination, read_ptr(), length);
   103→	}
   104→
   105→	/**
   106→	 * @brief Attempts to locate the provided value within the container.
   107→	 * 
   108→	 * @param value The value to locate.
   109→	 * 
   110→	 * @return The position of value or npos if not found.
   111→	 */
   112→	size_type find_first_of(value_type val) const noexcept {
   113→		const auto data = read_ptr();
   114→
   115→		for(size_type i = 0, j = size(); i < j; ++i) {
   116→			if(data[i] == val) {
   117→				return i;
   118→			}
   119→		}
   120→
   121→		return npos;
   122→	}
   123→
   124→	/**
   125→	 * @brief Skip over a number of bytes.
   126→	 * 
   127→	 * Skips over a number of bytes from the container. This should be used
   128→	 * if the container holds data that you don't care about but don't want
   129→	 * to have to read it to another buffer to access data beyond it.
   130→	 * 
   131→	 * @param length The number of bytes to skip.
   132→	 */
   133→	void skip(const size_type length) {
   134→		read_ += length;
   135→
   136→		if(read_ == write_) {
   137→			read_ = write_ = 0;
   138→		}
   139→	}
   140→
   141→	/**
   142→	 * @brief Advances the write cursor.
   143→	 * 
   144→	 * @param size The number of bytes by which to advance the write cursor.
   145→	 */
   146→	void advance_write(size_type bytes) {
   147→		assert(free() >= bytes);
   148→		write_ += bytes;
   149→	}
