   172→	/**
   173→	 * @brief Moves any unread data to the front of the buffer, freeing space at the end.
   174→	 * If a move is performed, pointers obtained from read/write_ptr() will be invalidated.
   175→	 * 
   176→	 * If the buffer contains no data available for reading, this function will have no effect.
   177→	 * 
   178→	 * @return True if additional space was made available.
   179→	 */
   180→	bool defragment() {
   181→		if(read_ == 0) {
   182→			return false;
   183→		}
   184→
   185→		write_ = size();
   186→		std::memmove(buffer_.data(), read_ptr(), write_);
   187→		read_ = 0;
   188→		return true;
   189→	}
   190→
   191→	/**
   192→	 * @brief Retrieves a reference to the specified index within the container.
   193→	 * 
   194→	 * @param index The index within the container.
