    21→class file_buffer final {
    22→public:
    23→	using size_type       = std::size_t;
    24→	using offset_type     = long;
    25→	using value_type      = char;
    26→	using contiguous      = is_non_contiguous;
    27→	using seeking         = unsupported;
    28→
    29→	static constexpr auto npos { static_cast<size_type>(-1) };
    30→
    31→private:
    32→	FILE* file_ = nullptr;
    33→	offset_type read_ = 0;
    34→	offset_type write_ = 0;
    35→	bool error_ = false;
    36→
    37→	/**
    38→	* @brief Explicitly close the underlying file handle.
    39→	* 
    40→	* This function will be called by the object's destructor
    41→	* and does not need to be called explicitly.
    42→	* 
    43→	* @note Idempotent.
    44→	*/
    45→	void close() {
    46→		if(file_) {
    47→			std::fclose(file_);
    48→			file_ = nullptr;
    49→		}
    50→	}
    51→
    52→public:
    53→	file_buffer(const std::filesystem::path& path)
    54→		: file_buffer(path.string().c_str()) { }
    55→
    56→	file_buffer(const char* path) {
    57→		file_ = std::fopen(path, "a+b");
    58→		
    59→		if(!file_) {
    60→			error_ = true;
    61→			return;
    62→		}
    63→		
    64→		if(std::fseek(file_, 0, SEEK_END)) {
    65→			error_ = true;
    66→			return;
    67→		}
    68→
    69→		write_ = std::ftell(file_);
    70→
    71→		if(write_ == -1) {
    72→			error_ = true;
    73→		}
    74→	}
    75→
    76→	file_buffer(file_buffer&& rhs) noexcept
    77→		: file_(rhs.file_),
    78→		  read_(rhs.read_),
    79→		  write_(rhs.write_),
    80→		  error_(rhs.error_) {
    81→		rhs.file_ = nullptr;
    82→	}
    83→
    84→	file_buffer& operator=(file_buffer&& rhs) noexcept {
    85→		std::exchange(file_, rhs.file_);
    86→		read_ = rhs.read_;
    87→		write_ = rhs.write_;
    88→		error_ = rhs.error_;
    89→		return *this;
    90→	}
    91→
    92→	file_buffer& operator=(const file_buffer&) = delete;
    93→	file_buffer(const file_buffer&) = delete;
    94→
    95→	~file_buffer() {
    96→		close();
    97→	}
    98→
    99→
   100→	/**
   101→	 * @brief Flush unwritten data.
   102→	 */
   103→	void flush() {
   104→		std::fflush(file_);
   105→	}
   106→
   107→	/**
   108→	 * @brief Reads a number of bytes to the provided buffer.
   109→	 * 
   110→	 * @param destination The buffer to copy the data to.
   111→	 */
   112→	template<typename T>
   113→	void read(T* destination) {
   114→		read(destination, sizeof(T));
   115→	}
   116→
   117→	/**
   118→	 * @brief Reads a number of bytes to the provided buffer.
   119→	 * 
   120→	 * @param destination The buffer to copy the data to.
   121→	 * @param length The number of bytes to read into the buffer.
   122→	 */
   123→	void read(void* destination, size_type length) {
   124→		if(error_) {
   125→			return;
   126→		}
   127→
   128→		if(std::fseek(file_, read_, 0)) {
   129→			error_ = true;
   130→			return;
   131→		}
   132→
   133→		if(std::fread(destination, length, 1, file_) != 1) {
   134→			error_ = true;
   135→			return;
   136→		}
   137→
   138→		read_ += length;
   139→	}
   140→
   141→	/**
   142→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   143→	 * the read cursor.
   144→	 * 
   145→	 * @param destination The buffer to copy the data to.
   146→	 */
   147→	template<typename T>
   148→	void copy(T* destination) {
   149→		copy(destination, sizeof(T));
   150→	}
   151→
   152→	/**
   153→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   154→	 * the read cursor.
   155→	 * 
   156→	 * @param destination The buffer to copy the data to.
   157→	 * @param length The number of bytes to copy.
   158→	 */
   159→	void copy(void* destination, size_type length) {
   160→		if(error_) {
   161→			return;
   162→		} else if(length > size()) {
   163→			error_ = true;
   164→			HEXI_THROW(buffer_underrun(length, read_, size()));
   165→		}
   166→
   167→		if(std::fseek(file_, read_, SEEK_SET)) {
   168→			error_ = true;
   169→			return;
   170→		}
   171→		
   172→		if(std::fread(destination, length, 1, file_) != 1) {
   173→			error_ = true;
   174→			return;
   175→		}
   176→	}
   177→
   178→	/**
   179→	 * @brief Attempts to locate the provided value within the container.
   180→	 * 
   181→	 * @param value The value to locate.
   182→	 * 
   183→	 * @return The position of value or npos if not found.
   184→	 */
   185→	size_type find_first_of(value_type val) noexcept {
   186→		if(error_) {
   187→			return npos;
   188→		}
   189→
   190→		if(std::fseek(file_, read_, SEEK_SET)) {
   191→			error_ = true;
   192→			return npos;
   193→		}
   194→
   195→		value_type buffer{};
   196→
   197→		for(size_type i = 0, j = size(); i < j; ++i) {
   198→			if(std::fread(&buffer, sizeof(value_type), 1, file_) != 1) {
   199→				error_ = true;
   200→				return npos;
   201→			}
   202→
   203→			if(buffer == val) {
   204→				return i;
   205→			}
   206→		}
   207→
   208→		return npos;
   209→	}
   210→
   211→	/**
   212→	 * @brief Skip a requested number of bytes.
   213→	 *
   214→	 * Skips over a number of bytes from the file. This should be used
   215→	 * if the file holds data that you don't care about but don't want
   216→	 * to have to read it to another buffer to access data beyond it.
   217→	 * 
   218→	 * @param length The number of bytes to skip.
   219→	 */
   220→	void skip(const size_type length) {
   221→		read_ += length;
   222→	}
   223→
   224→	/**
   225→	 * @brief Whether the container is empty.
   226→	 * 
   227→	 * @return Returns true if the container is empty (has no data to be read).
   228→	 */
   229→	[[nodiscard]]
   230→	bool empty() const {
   231→		return write_ == read_;
   232→	}
   233→
   234→	/**
   235→	 * @brief Determine whether the adaptor supports write seeking.
   236→	 * 
   237→	 * This is determined at compile-time and does not need to checked at
   238→	 * run-time.
   239→	 * 
   240→	 * @return True if write seeking is supported, otherwise false.
   241→	 */
   242→	constexpr static bool can_write_seek() {
   243→		return std::is_same_v<seeking, supported>;
   244→	}
   245→
   246→	/**
   247→	 * @brief Write data to the container.
   248→	 * 
   249→	 * @param source Pointer to the data to be written.
   250→	 */
   251→	void write(const auto& source) {
   252→		write(&source, sizeof(source));
   253→	}
   254→
   255→	/**
   256→	 * @brief Write provided data to the file.
   257→	 * 
   258→	 * @param source Pointer to the data to be written.
   259→	 * @param length Number of bytes to write from the source.
   260→	 */
   261→	void write(const void* source, size_type length) {
   262→		if(error_) {
   263→			return;
   264→		}
   265→		
   266→		if(std::fseek(file_, write_, SEEK_SET)) {
   267→			error_ = true;
   268→			return;
   269→		}
   270→
   271→		if(std::fwrite(source, length, 1, file_) != 1) {
   272→			error_ = true;
   273→			return;
   274→		}
   275→
   276→		write_ += length;
   277→	}
   278→
   279→
   280→	/**
   281→	 * @brief Returns the amount of data available in the file.
   282→	 * 
   283→	 * @return The number of bytes of data available to read from the file.
   284→	 */
   285→	size_type size() const {
   286→		return static_cast<size_type>(write_) - read_;
   287→	}
   288→
   289→	/** 
   290→	 * @brief Retrieve the file handle.
   291→	 * 
   292→	 * @return The file handle.
   293→	 */
   294→	FILE* handle() {
   295→		return file_;
   296→	}
   297→
   298→	/** 
   299→	 * @brief Retrieve the file handle.
   300→	 * 
   301→	 * @return The file handle.
   302→	 */
   303→	const FILE* handle() const {
   304→		return file_;
   305→	}
   306→
   307→	/** 
   308→	 * @return True if an error has occurred during file operations.
   309→	 */
   310→	bool error() const {
   311→		return error_;
   312→	}
   313→
   314→	/** 
   315→	 * @return True if no error has occurred during file operations.
   316→	 */
   317→	operator bool() const {
   318→		return !error();
   319→	}
   320→};
