    96→		assert(!region_overlap(buffer_.data(), buffer_.size(), destination, length));
    97→
    98→		if(length > size()) {
    99→			HEXI_THROW(buffer_underrun(length, read_, size()));
   100→		}
   101→
   102→		std::memcpy(destination, read_ptr(), length);
   103→	}
