    30→template<std::size_t block_size, byte_type storage_type = std::byte>
    31→struct intrusive_storage final {
    32→	using value_type = storage_type;
    33→	using offset_type = std::remove_const_t<decltype(block_size)>;
    34→
    35→	offset_type read_offset = 0;
    36→	offset_type write_offset = 0;
    37→	intrusive_node node {};
    38→	std::array<value_type, block_size> storage;
    39→
    40→	/**
    41→	 * @brief Clear the container.
    42→	 * 
    43→	 * Resets the read and write offsets, does not explicitly
    44→	 * erase the data contained within the buffer but should
    45→	 * be treated as such.
    46→	 */
    47→	void clear() {
    48→		read_offset = 0;
    49→		write_offset = 0;
    50→	}
    51→
    52→	/**
    53→	 * @brief Write provided data to the container.
    54→	 * 
    55→	 * If the container size is lower than requested number of bytes,
    56→	 * the request will be capped at the number of bytes available.
    57→	 * 
    58→	 * @note The source buffer must not overlap with the underlying buffer.
    59→	 * 
    60→	 * @param source Pointer to the data to be written.
    61→	 * @param length Number of bytes to write from the source.
    62→	 * 
    63→	 * @return The number of bytes copied, which may be less than requested.
    64→	 */
    65→	std::size_t write(const auto source, std::size_t length) {
    66→		assert(!region_overlap(source, length, storage.data(), storage.size()));
    67→		std::size_t write_len = block_size - write_offset;
    68→
    69→		if(write_len > length) {
    70→			write_len = length;
    71→		}
    72→
    73→		std::memcpy(storage.data() + write_offset, source, write_len);
    74→		write_offset += static_cast<offset_type>(write_len);
    75→		return write_len;
    76→	}
    77→
    78→	/**
    79→	 * @brief Copies a number of bytes to the provided buffer but without
    80→	 * advancing the read cursor.
    81→	 * 
    82→	 * If the container size is lower than requested number of bytes,
    83→	 * the request will be capped at the number of bytes available.
    84→	 * 
    85→	 * @note The destination buffer must not overlap with the underlying buffer.
    86→	 * 
    87→	 * @param[out] destination The buffer to copy the data to.
    88→	 * @param length The number of bytes to copy.
    89→	 * 
    90→	 * @return The number of bytes copied, which may be less than requested.
    91→	 */
    92→	std::size_t copy(auto destination, const std::size_t length) const {
    93→		assert(!region_overlap(storage.data(), storage.size(), destination, length));
    94→		std::size_t read_len = block_size - read_offset;
    95→
    96→		if(read_len > length) {
    97→			read_len = length;
    98→		}
    99→
   100→		std::memcpy(destination, storage.data() + read_offset, read_len);
   101→		return read_len;
   102→	}
