   908→	/**
   909→	 * @brief Provides a string_view over the stream's data, up to the terminator value.
   910→	 * 
   911→	 * @param terminator An optional terminating/sentinel value.
   912→	 * 
   913→	 * @return A string view over data up to the provided terminator.
   914→	 * An empty string_view if a terminator is not found
   915→	 */
   916→	std::string_view view(value_type terminator = value_type(0)) requires contiguous<buf_type> {
   917→		const auto pos = buffer_.find_first_of(terminator);
   918→
   919→		if(pos == buf_type::npos) {
   920→			return {};
   921→		}
   922→
   923→		std::string_view view { reinterpret_cast<char*>(buffer_.read_ptr()), pos };
   924→
   925→		// no need to enforce bounds, we know there's enough data
   926→		buffer_.skip(pos + 1);
   927→		total_read_ += (pos + 1);
   928→		return view;
   929→	}
   930→
   931→	/**
   932→	 * @brief Provides a span over the specified number of elements in the stream.
   933→	 * 
   934→	 * @param count The number of elements the span will provide a view over.
   935→	 * 
   936→	 * @return A span representing a view over the requested number of elements
   937→	 * in the stream.
   938→	 * 
   939→	 * @note The stream will error if the stream does not contain the requested amount of data.
   940→	 */
   941→	template<typename out_type = value_type>
   942→	std::span<out_type> span(size_type count) requires contiguous<buf_type> {
   943→		std::span view { reinterpret_cast<out_type*>(buffer_.read_ptr()), count };
   944→		skip(sizeof(out_type) * count);
   945→		return (state_ == stream_state::ok? view : std::span<out_type>());
   946→	}
