   206→	/**
   207→	 * @brief Deserialises a string that was previously written with a
   208→	 * null terminator.
   209→	 * 
   210→	 * @param[out] adaptor std::string to hold the result.
   211→	 * 
   212→	 * @return Reference to the current stream.
   213→	 */
   214→	binary_stream_reader& operator>>(null_terminated<std::string> adaptor) {
   215→		auto pos = buffer_.find_first_of(std::byte{0});
   216→
   217→		if(pos == buffer_.npos) {
   218→			adaptor->clear();
   219→			return *this;
   220→		}
   221→
   222→		STREAM_READ_BOUNDS_ENFORCE(pos + 1, *this); // include null terminator
   223→
   224→		adaptor->resize_and_overwrite(pos, [&](char* strbuf, std::size_t size) {
   225→			buffer_.read(strbuf, pos);
   226→			return size;
   227→		});
   228→
   229→		buffer_.skip(1); // skip null terminator
   230→		return *this;
   231→	}
